<student_code untrusted="true">
=== submission_06.ino ===
   1| // Lab 4: debounced LED toggle
   2| //
   3| // Approach: after a toggle, ignore the button for a lockout period so
   4| // the contact bounce can't cause extra toggles. Uses millis() so there
   5| // is no blocking delay.
   6| //
   7| // D2  - button to GND, INPUT_PULLUP (LOW while pressed)
   8| // D13 - LED
   9| // Serial1 9600 - prints new state
  10| 
  11| #define BUTTON_PIN  2
  12| #define LED_PIN     LED_BUILTIN
  13| #define LOCKOUT_MS  200
  14| 
  15| bool led = false;
  16| unsigned long lastToggle = 0;
  17| 
  18| void setup() {
  19|   pinMode(BUTTON_PIN, INPUT_PULLUP);
  20|   pinMode(LED_PIN, OUTPUT);
  21|   digitalWrite(LED_PIN, LOW);
  22|   Serial1.begin(9600);
  23| }
  24| 
  25| void loop() {
  26|   // pressed, and we're outside the lockout window
  27|   if (digitalRead(BUTTON_PIN) == LOW && millis() - lastToggle >= LOCKOUT_MS) {
  28|     led = !led;
  29|     digitalWrite(LED_PIN, led ? HIGH : LOW);
  30|     Serial1.println(led ? "ON" : "OFF");
  31|     lastToggle = millis();
  32|   }
  33| }
</student_code>
